const resp = $input.first().json;
const items = Array.isArray(resp) ? resp : (resp.items ?? resp.data ?? []);
const paineis = items.filter(p => !p.archived);
if (paineis.length === 0) throw new Error('Nenhum painel encontrado para a conta.');

const avisos = [];
if (paineis.length > 1) avisos.push(`Conta tem ${paineis.length} paineis; usando o primeiro: "${paineis[0].title}". Confira se e o correto.`);

const painel = paineis[0];
const steps = (painel.steps || []).filter(s => !s.archived);
let etapa = steps.find(s => s.isInitial) || steps.slice().sort((a,b)=> (a.position||0)-(b.position||0))[0];
if (!etapa) throw new Error('Painel sem etapas validas.');
if (!steps.find(s => s.isInitial)) avisos.push('Nenhuma etapa marcada como inicial; usei a de menor posicao.');

return [{ json: { panel_id: painel.id, panel_title: painel.title, step_id: etapa.id, step_title: etapa.title, avisos } }];

// Match por palavra-chave e monta a LINHA PLANA p/ a planilha.
// Ambiguidade (0 ou >1 candidatas) => registra em status_obs p/ revisao manual.
const entradas = $('Entradas').first().json;
const escolha = $('Escolher Painel e Etapa').first().json;

const painelResp = $('Tags Card Painel').first().json;
const cardTags = painelResp.tags || [];

const contatoResp = $('Tags Contato').first().json;
const contatoTags = Array.isArray(contatoResp) ? contatoResp : (contatoResp.items ?? []);

const norm = (s) => (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const achar = (tags, kw) => tags.filter(t => norm(t.name).includes(kw));

const REGRAS = [
  { p: 'fb',  kw: 'facebook' },
  { p: 'ig',  kw: 'instagram' },
  { p: 'org', kw: 'organico' }
];
const ROTULO = { fb: 'Facebook', ig: 'Instagram', org: 'Organico' };

const row = {
  helena_company_id: entradas.companyId,
  nome: (entradas.nome && entradas.nome.trim()) ? entradas.nome.trim() : escolha.panel_title,
  helena_token: entradas.helena_token,
  panel_id: escolha.panel_id,
  step_id: escolha.step_id,
  ativo: 'true'
};

const avisos = [...(escolha.avisos || [])];
for (const r of REGRAS) {
  const card = achar(cardTags, r.kw);
  const contato = achar(contatoTags, r.kw);
  if (card.length !== 1) avisos.push(`Tag de CARD ${ROTULO[r.p]}: ${card.length} candidata(s) -> ${card.map(t=>t.name).join(' | ') || 'nenhuma'}`);
  if (contato.length !== 1) avisos.push(`Tag de CONTATO ${ROTULO[r.p]}: ${contato.length} candidata(s) -> ${contato.map(t=>t.name).join(' | ') || 'nenhuma'}`);
  row[`${r.p}_tag_nome`] = ROTULO[r.p];
  row[`${r.p}_panel_tag_id`] = card[0]?.id ?? '';
  row[`${r.p}_contact_tag_id`] = contato[0]?.id ?? '';
}
row.status_obs = avisos.length ? avisos.join(' | ') : 'ok';

return [{ json: { row, avisos, resumo: { painel: escolha.panel_title, etapa: escolha.step_title } } }];

const m = $('Montar Linha').first().json;
const pendente = (m.avisos && m.avisos.length) ? m.avisos : [];
return [{ json: {
  resumo: m.resumo,
  linha_gravada: m.row,
  avisos: pendente,
  acao_necessaria: pendente.length ? 'Revisar/corrigir os IDs marcados em status_obs na planilha.' : 'Nenhuma. Config completa.'
} }];
